examples.code:
:root {
  /* палитра */
  --bg: #06070f;
  --surface: rgba(255, 255, 255, .045);
  --border: rgba(255, 255, 255, .085);
  --text: #eaeefb;
  --text-dim: #a3adcb;
  --accent: #6366f1;
  --accent-2: #22d3ee;

  /* геометрия и ритм */
  --r-sm: 10px;
  --r-md: 16px;
  --r-pill: 999px;
  --space: 16px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: var(--space);
  color: var(--text-dim);
}

